mapper.select:
SELECT cp.id, cp.customer_id, cp.material_id, cp.price, cp.tax_rate, cp.remark, c.code AS customer_code, c.name AS customer_name, m.code AS material_code, m.name AS material_name, m.spec, m.unit FROM scm_customer_price cp JOIN scm_customer c ON c.id = cp.customer_id JOIN wms_material m ON m.id = cp.material_id
cp.customer_id = #{customerId} AND (c.code LIKE CONCAT('%', #{keyword}, '%') OR c.name LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY c.code, m.code LIMIT #{limit}
